ntent_path":"content/lessons/deep-learning.json#4"},{"id":"c56e8a7a-dc18-5e13-834d-9301cfd5a789","skill_uri":"careerprep:skill/git","lesson_no":1,"title":"Commits and history","content_path":"content/lessons/git.json#1"},{"id":"8f8cde24-9ac6-5f55-8165-c0c11d00bff8","skill_uri":"careerprep:skill/git","lesson_no":2,"title":"Working with branches","content_path":"content/lessons/git.json#2"},{"id":"714b5540-a501-5751-8f75-d7a32e15a919","skill_uri":"careerprep:skill/git","lesson_no":3,"title":"Merging and conflicts","content_path":"content/lessons/git.json#3"},{"id":"48e31a92-b146-5263-b1cc-5668fc43d3b6","skill_uri":"careerprep:skill/git","lesson_no":4,"title":"Pull requests","content_path":"content/lessons/git.json#4"},{"id":"69a92d61-084c-5629-bc2a-037647df64d6","skill_uri":"careerprep:skill/machine-learning","lesson_no":1,"title":"What a model learns","content_path":"content/lessons/machine-learning.json#1"},{"id":"d8afeb7e-0628-5cad-8144-04374b8703af","skill_uri":"careerprep:skill/machine-learning","lesson_no":2,"title":"Training and test data","content_path":"content/lessons/machine-learning.json#2"},{"id":"aedca2ec-a141-5d3a-b992-db6618ec0b84","skill_uri":"careerprep:skill/machine-learning","lesson_no":3,"title":"Your first classifier","content_path":"content/lessons/machine-learning.json#3"},{"id":"56f500c1-eb2b-52e9-8a00-02192019a767","skill_uri":"careerprep:skill/machine-learning","lesson_no":4,"title":"Choosing features","content_path":"content/lessons/machine-learning.json#4"},{"id":"c0c50c64-adab-50c9-809b-97405b11338a","skill_uri":"careerprep:skill/model-deployment","lesson_no":1,"title":"From notebook to script","content_path":"content/lessons/model-deployment.json#1"},{"id":"c863b253-7494-59d1-a168-854721895fea","skill_uri":"careerprep:skill/model-deployment","lesson_no":2,"title":"A simple prediction API","content_path":"content/lessons/model-deployment.json#2"},{"id":"852beea6-928d-56a9-9f48-d1dd4eb90886","skill_uri":"careerprep:skill/model-deployment","lesson_no":3,"title":"Running it in the cloud","content_path":"content/lessons/model-deployment.json#3"},{"id":"a26680fd-b7cf-59ed-a091-9c1644d8ca6e","skill_uri":"careerprep:skill/model-deployment","lesson_no":4,"title":"Watching it after launch","content_path":"content/lessons/model-deployment.json#4"},{"id":"976d4424-3ca4-52e5-9518-0218dc600158","skill_uri":"careerprep:skill/model-evaluation","lesson_no":1,"title":"Accuracy and its limits","content_path":"content/lessons/model-evaluation.json#1"},{"id":"95985ab6-37e7-521c-a8be-0e917b9b636c","skill_uri":"careerprep:skill/model-evaluation","lesson_no":2,"title":"Precision and recall","content_path":"content/lessons/model-evaluation.json#2"},{"id":"c4cff695-b86a-5316-8a59-0cadece380df","skill_uri":"careerprep:skill/model-evaluation","lesson_no":3,"title":"Overfitting","content_path":"content/lessons/model-evaluation.json#3"},{"id":"4de99eb3-7b05-5280-9982-ffdbeee47079","skill_uri":"careerprep:skill/model-evaluation","lesson_no":4,"title":"Cross-validation","content_path":"content/lessons/model-evaluation.json#4"}],"check_questions":[{"id":"cfd61d94-1688-5afb-b90b-df61e2ff4c13","lesson_id":"3d49f4b9-1b26-5562-b700-3f9343d7ea42","position":1,"prompt":"x has shape [32, 10] and w has shape [10, 4]. What is the shape of x @ w?","options":[{"id":"a","text":"[10, 4]"},{"id":"b","text":"[32, 4]"},{"id":"c","text":"[32, 10]"},{"id":"d","text":"It fails"}],"answer_key":"b"},{"id":"13334daf-333c-58db-b499-1e045414b214","lesson_id":"85d99aef-37ed-58d5-8d2b-dcf03c19ffc6","position":2,"prompt":"Why does a network need an activation such as ReLU between linear layers?","options":[{"id":"a","text":"To make training faster on a GPU"},{"id":"b","text":"Without it, stacked linear layers act like one linear layer"},{"id":"c","text":"To turn the outputs into probabilities"},{"id":"d","text":"To stop overfitting"}],"answer_key":"b"},{"id":"337b4d4a-b653-5ec9-abb9-8a72128236c2","lesson_id":"9bca84c1-86ec-5bf7-b676-8e97dfa5b482","position":3,"prompt":"In a training step, what must happen right before loss.backward()?","options":[{"id":"a","text":"optimizer.step()"},{"id":"b","text":"optimizer.zero_grad()"},{"id":"c","text":"model.eval()"},{"id":"d","text":"torch.save()"}],"answer_key":"b"},{"id":"cfb2768c-1c1d-570d-aafa-4cf6244475fc","lesson_id":"9bca84c1-86ec-5bf7-b676-8e97dfa5b482","position":4,"prompt":"What should you pass to nn.CrossEntropyLoss?","options":[{"id":"a","text":"Softmax probabilities and one-hot labels"},{"id":"b","text":"Raw logits and int64 class indices"},{"id":"c","text":"Predicted class indices and true class indices"},{"id":"d","text":"Raw logits and float labels between 0 and 1"}],"answer_key":"b"},{"id":"abd5ce26-f0cb-56f2-9098-f3b99bd63467","lesson_id":"cb5e9855-5110-5007-b04d-c33c3ba46a6c","position":5,"prompt":"What is the usual way to save a trained PyTorch model?","options":[{"id":"a","text":"torch.save(model.state_dict(), \"model.pt\")"},{"id":"b","text":"Copy the .py file"},{"id":"c","text":"print(model) into a text file"},{"id":"d","text":"Save the training loss list"}],"answer_key":"a"},{"id":"e0daa61e-2997-568a-a2f9-7c4b5bad3d54","lesson_id":"c56e8a7a-dc18-5e13-834d-9301cfd5a789","position":1,"prompt":"You edited three files but only want two of them in the next commit. What do you do?","options":[{"id":"a","text":"Run git commit -a, then undo the third file"},{"id":"b","text":"git add the two files, then git commit"},{"id":"c","text":"Delete the third file, then commit everything"},{"id":"d","text":"Run git push for the two files"}],"answer_key":"b"},{"id":"5c377689-2042-5132-89b9-80704da9add0","lesson_id":"c56e8a7a-dc18-5e13-834d-9301cfd5a789","position":2,"prompt":"Which commit message is the most useful?","options":[{"id":"a","text":"update"},{"id":"b","text":"Fixed stuff"},{"id":"c","text":"Show an error when the email field is empty"},{"id":"d","text":"asdf"}],"answer_key":"c"},{"id":"6426e7a8-6213-5b43-89aa-6d463cb77c33","lesson_id":"8f8cde24-9ac6-5f55-8165-c0c11d00bff8","position":3,"prompt":"Which command creates a branch called fix-header and moves you onto it?","options":[{"id":"a","text":"git switch -c fix-header"},{"id":"b","text":"git branch -d fix-header"},{"id":"c","text":"git merge fix-header"},{"id":"d","text":"git commit fix-header"}],"answer_key":"a"},{"id":"95680d17-2943-57ad-9273-dd971e84a2d7","lesson_id":"714b5540-a501-5751-8f75-d7a32e15a919","position":4,"prompt":"When does a merge conflict happen?","options":[{"id":"a","text":"When a branch has no commits"},{"id":"b","text":"When two branches changed the same lines of the same file"},{"id":"c","text":"When you switch branches too often"},{"id":"d","text":"When the repository has more than two branches"}],"answer_key":"b"},{"id":"a3c5cfa5-dd92-5723-93d3-15443b31e3a2","lesson_id":"48e31a92-b146-5263-b1cc-5668fc43d3b6","position":5,"prompt":"You pushed a commit that contains your database password. What must you do?","options":[{"id":"a","text":"Nothing, the repository is private"},{"id":"b","text":"Delete the file in a new commit and carry on"},{"id":"c","text":"Change the password, then remove the file and add it to .gitignore"},{"id":"d","text":"Rename the file so nobody finds it"}],"answer_key":"c"},{"id":"8a122826-591b-52b0-8733-77bca5c75590","lesson_id":"69a92d61-084c-5629-bc2a-037647df64d6","position":1,"prompt":"A model predicts a student's final mark out of 100. What kind of task is this?","options":[{"id":"a","text":"Classification"},{"id":"b","text":"Regression"},{"id":"c","text":"Clustering"},{"id":"d","text":"Unsupervised learning"}],"answer_key":"b"},{"id":"601b9cad-67db-550f-9115-369764b8eebf","lesson_id":"d8afeb7e-0628-5cad-8144-04374b8703af","position":2,"prompt":"Why do you keep a test set aside?","options":[{"id":"a","text":"To make training faster"},{"id":"b","text":"To measure the model on data it has not seen"},{"id":"c","text":"To give the model more examples to learn from"},{"id":"d","text":"Because scikit-learn needs two files"}],"answer_key":"b"},{"id":"14f3e2a1-7fc1-5b62-98b6-d917d2ce4781","lesson_id":"aedca2ec-a141-5d3a-b992-db6618ec0b84","position":3,"prompt":"Your classifier scores 0.82 accuracy. Always guessing the most common class scores 0.80. What does this tell you?","options":[{"id":"a","text":"The model is excellent"},{"id":"b","text":"The model adds very little over a simple baseline"},{"id":"c","text":"The test set is too large"},{"id":"d","text":"Accuracy cannot be used"}],"answer_key":"b"},{"id":"d2d4ba86-959c-5aee-8456-d45343f3ef30","lesson_id":"aedca2ec-a141-5d3a-b992-db6618ec0b84","position":4,"prompt":"In scikit-learn, which call learns from the training data?","options":[{"id":"a","text":"model.predict(X_train)"},{"id":"b","text":"model.score(X_train, y_train)"},{"id":"c","text":"model.fit(X_train, y_train)"},{"id":"d","text":"train_test_split(X, y)"}],"answer_key":"c"},{"id":"203e78b1-dd97-5776-b967-389d3d2bf4ba","lesson_id":"56f500c1-eb2b-52e9-8a00-02192019a767","position":5,"prompt":"Where should a StandardScaler learn its mean and spread?","options":[{"id":"a","text":"From the whole dataset before splitting"},{"id":"b","text":"From the test set"},{"id":"c","text":"From the training set only"},{"id":"d","text":"It does not matter"}],"answer_key":"c"},{"id":"c2811186-d6f0-588c-8624-0339e44b8f9d","lesson_id":"c0c50c64-adab-50c9-809b-97405b11338a","position":1,"prompt":"Why save the whole scikit-learn Pipeline instead of only the final model?","options":[{"id":"a","text":"The file is smaller"},{"id":"b","text":"The same preparation steps, such as scaling, run again at prediction time"},{"id":"c","text":"Pipelines train faster"},{"id":"d","text":"joblib cannot save models on their own"}],"answer_key":"b"},{"id":"9c382558-6b39-5def-a545-65f18bbf1369","lesson_id":"c863b253-7494-59d1-a168-854721895fea","position":2,"prompt":"In a FastAPI app, when should the model file be loaded?","options":[{"id":"a","text":"Inside the /predict function, on every request"},{"id":"b","text":"Once, when the app starts"},{"id":"c","text":"Only when /health is called"},{"id":"d","text":"In the browser"}],"answer_key":"b"},{"id":"957748bf-1aaa-5445-9a85-49f8cb1ed88f","lesson_id":"c863b253-7494-59d1-a168-854721895fea","position":3,"prompt":"A client sends {\"sepal_length\": \"long\"} to your /predict endpoint, which uses a Pydantic model with float fields. What happens?","options":[{"id":"a","text":"The model predicts anyway"},{"id":"b","text":"FastAPI returns a 422 error saying the input is invalid"},{"id":"c","text":"The server crashes"},{"id":"d","text":"The value is set to 0"}],"answer_key":"b"},{"id":"1d7937ab-9e02-523d-9736-ccf251c37494","lesson_id":"852beea6-928d-56a9-9f48-d1dd4eb90886","position":4,"prompt":"Where should an API key used by your service come from?","options":[{"id":"a","text":"Written in app.py"},{"id":"b","text":"Copied into the Docker image"},{"id":"c","text":"An environment variable set on the server"},{"id":"d","text":"A comment in the Dockerfile"}],"answer_key":"c"},{"id":"2328a94b-38d7-5c5a-95e1-fb36e2000156","lesson_id":"a26680fd-b7cf-59ed-a091-9c1644d8ca6e","position":5,"prompt":"The code has not changed, but live accuracy has dropped over two months. What is the most likely cause?","options":[{"id":"a","text":"The server is too slow"},{"id":"b","text":"The incoming data has drifted away from the training data"},{"id":"c","text":"The Docker image expired"},{"id":"d","text":"The /health endpoint failed"}],"answer_key":"b"},{"id":"d4f13863-94f6-552a-b7ca-4ac871bb3bf0","lesson_id":"976d4424-3ca4-52e5-9518-0218dc600158","position":1,"prompt":"99 of 100 transactions are normal. A model always predicts \"normal\". What is its accuracy, and is it useful for finding fraud?","options":[{"id":"a","text":"0.99, and yes it is useful"},{"id":"b","text":"0.99, but it finds no fraud at all"},{"id":"c","text":"0.50, because there are two classes"},{"id":"d","text":"0.01, because it never predicts fraud"}],"answer_key":"b"},{"id":"f684c0c1-e097-52c4-b0b6-0b8dbeaa2f0a","lesson_id":"95985ab6-37e7-521c-a8be-0e917b9b636c","position":2,"prompt":"A model flags 20 items; 15 are truly positive. There were 30 positives in total. What are precision and recall?","options":[{"id":"a","text":"Precision 0.75, recall 0.50"},{"id":"b","text":"Precision 0.50, recall 0.75"},{"id":"c","text":"Precision 0.75, recall 0.75"},{"id":"d","text":"Precision 0.67, recall 0.50"}],"answer_key":"a"},{"id":"f2489a52-5797-5ee2-8167-b72ae38c2d6a","lesson_id":"95985ab6-37e7-521c-a8be-0e917b9b636c","position":3,"prompt":"A clinic screen must miss as few sick patients as possible. Which measure matters most?","options":[{"id":"a","text":"Precision"},{"id":"b","text":"Recall"},{"id":"c","text":"Training accuracy"},{"id":"d","text":"The number of features"}],"answer_key":"b"},{"id":"fd1dff80-4418-5cd9-96a5-58ac02fef7b2","lesson_id":"c4cff695-b86a-5316-8a59-0cadece380df","position":4,"prompt":"Training accuracy is 0.99 and test accuracy is 0.68. What is the most likely problem?","options":[{"id":"a","text":"Underfitting"},{"id":"b","text":"Overfitting"},{"id":"c","text":"The test set is too easy"},{"id":"d","text":"The labels are all the same"}],"answer_key":"b"},{"id":"d9e3a46e-4104-5faa-9062-8e76687dda1c","lesson_id":"4de99eb3-7b05-5280-9982-ffdbeee47079","position":5,"prompt":"What does 5-fold cross-validation give you that a single split does not?","options":[{"id":"a","text":"A model that never overfits"},{"id":"b","text":"Five scores, so you see the average and how much it varies"},{"id":"c","text":"A bigger training set for the final model"},{"id":"d","text":"A way to skip the test set"}],"answer_key":"b"}],"interview_questions":[{"key":"2519-03:technical:1","code":"2519-03","round":"technical","position":1,"prompt":"Explain the difference between an INNER JOIN and a LEFT JOIN, with an example.","rubric":{"situation":["when i ","when we ","when our","when my","in my","in our","on my","on our","during","for my","for our","at my","proje